function isAdult(age) { return age >= 18; }
console.log(isAdult(17));
console.log(isAdult(20));

function addStock(current, added) { return current + added; }
function removeStock(current, sold) { return current - sold; }
console.log(addStock(8, 2));
console.log(removeStock(8, 3));

function discounted(price, percent) { return price - price * percent / 100; }
console.log(discounted(100, 10));
console.log(discounted(250, 10));
